The following reproducer demonstrates the performance hit, and shows the above patch restoring the performance:

<details>

<summary>Repro</summary>

```c++
#include <ATen/Functions.h>
#include <torch/mps.h>
#include <torch/version.h>

#include <chrono>
#include <cstdio>

template <at::ScalarType DType, typename FPType>
void test(const char * name) {
    const auto opts = at::TensorOptions().device(at::DeviceType::MPS).dtype(DType);
    const auto in = at::rand({16, 8, 343, 64}, opts);

    const auto start = std::chrono::high_resolution_clock::now();
    const size_t iters = 10'000;
    for (size_t i = 0; i < iters; i++) {
        at::mul(in, FPType(1));
    }
    torch::mps::synchronize();
    const auto stop = std::chrono::high_resolution_clock::now();

    const auto dt = std::chrono::duration_cast<std::chrono::microseconds>(stop - start).count();
    printf("  %s took %lldus (%lldus/iter)\n", name, dt, dt / iters);
}

int main() {
    printf("Using torch %s\n", TORCH_VERSION);
    test<at::kHalf, at::Half>("Tensor[half] x half");
    test<at::kHalf, float>("Tensor[half] x float");
    test<at::kFloat, at::Half>("Tensor[float] x half");
    test<at::kFloat, float>("Tensor[float] x float");
}
```

```
Using torch 2.7.1
  Tensor[half] x half took 255576us (25us/iter)
  Tensor[half] x float took 253359us (25us/iter)
  Tensor[float] x half took 305680us (30us/iter)
  Tensor[float] x float took 271972us (27us/iter)

Using torch 2.9.0
  Tensor[half] x half took 827073us (82us/iter)
  Tensor[half] x float took 811882us (81us/iter)
  Tensor[float] x half took 821109us (82us/iter)
  Tensor[float] x float took 791635us (79us/iter)

Using torch 2.9.0 + above patch
  Tensor[half] x half took 222195us (22us/iter)
  Tensor[half] x float took 213411us (21us/iter)
  Tensor[float] x half took 318331us (31us/iter)
  Tensor[float] x float took 284615us (28us/iter)
```

</details>

